package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.PushbackInputStream;
import java.math.*;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;
import java.util.zip.ZipEntry;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipArchiveEntry;
import org.apache.commons.compress.archivers.zip.ZipArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipException;
import org.apache.commons.compress.compressors.bzip2.BZip2CompressorInputStream;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.IOUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveInputStream_getNextZipEntry_TriageGen2Test {

    private static final int LFH_SIG = 0x04034b50;
    private static final int CFH_SIG = 0x02014b50;
    private static final int AED_SIG = 0x06054b50;

    /**
     * Helper to create a valid LFH byte array
     */
    private byte[] createLFH(String name, int method, long crc, long size, long compressedSize, boolean hasDataDescriptor) {
        byte[] nameBytes = name.getBytes();
        int extraLen = 0;
        int headerSize = 30; // Base LFH size
        if (!hasDataDescriptor) {
            headerSize += 12; // crc(4) + mod(2) + mod(2) + size(4) -> actually logic uses WORD/SHORT
            // Based on code: off += WORD (crc), off += WORD (unused), off += WORD (size)
            // Total 12 bytes for non-descriptor
        } else {
            headerSize += 12; // 3 * WORD
        }

        // The code logic for off calculation:
        // sig(4) + ver(2) + flag(2) + method(2) + time(4) + [crc(4)+unused(2)+size(4)] OR [3*4] + nameLen(2) + extraLen(2)
        // Let's build it according to the offsets in the method

        int totalSize = 30 + (hasDataDescriptor ? 12 : 12) + 2 + 2 + nameBytes.length + extraLen;
        ByteBuffer bb = ByteBuffer.allocate(totalSize).order(ByteOrder.LITTLE_ENDIAN);

        bb.putInt(LFH_SIG);
        bb.putShort((short) 0x0200); // version made by + flags
        bb.putShort((short) 0);      // flags
        bb.putShort((short) method);
        bb.putInt(0);                // time

        if (!hasDataDescriptor) {
            bb.putInt((int) crc);
            bb.putShort((short) 0);
            bb.putInt((int) size);
        } else {
            bb.putInt(0); bb.putInt(0); bb.putInt(0);
        }

        bb.putShort((short) nameBytes.length);
        bb.putShort((short) extraLen);
        bb.put(nameBytes);

        return bb.array();
    }

    @Test
    public void testGetNextZipEntry_ClosedOrHitCentralDirectory() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[10]);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);
        zais.close();
        assertNull(zais.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_EOF() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);
        assertNull(zais.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_UnexpectedSignature() throws IOException {
        ByteBuffer bb = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt(0xDEADBEEF);
        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        try {
            zais.getNextZipEntry();
            fail("Should have thrown ZipException");
        } catch (ZipException e) {
            assertTrue(e.getMessage().contains("Unexpected record signature"));
        }
    }

    @Test
    public void testGetNextZipEntry_CentralDirectorySignature() throws IOException {
        ByteBuffer bb = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt(CFH_SIG);
        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        assertNull(zais.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_AEDSignature() throws IOException {
        ByteBuffer bb = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt(AED_SIG);
        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        assertNull(zais.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_SuccessStandard() throws IOException {
        byte[] lfh = createLFH("test.txt", 0, 1234L, 100L, 50L, false);
        InputStream is = new ByteArrayInputStream(lfh);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zais.getNextZipEntry();
        assertNotNull(entry);
        assertEquals("test.txt", entry.getName());
        assertEquals(1234L, entry.getCrc());
    }

    @Test
    public void testGetNextZipEntry_SuccessWithDataDescriptor() throws IOException {
        // Note: The code logic for data descriptor sets current.hasDataDescriptor = true
        // and then skips 3 * WORD in the header parsing.
        byte[] lfh = createLFH("data.bin", 0, 0, 0, 0, true);
        InputStream is = new ByteArrayInputStream(lfh);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zais.getNextZipEntry();
        assertNotNull(entry);
        assertEquals("data.bin", entry.getName());
    }

    @Test
    public void testGetNextZipEntry_MultipleEntries() throws IOException {
        byte[] lfh1 = createLFH("1.txt", 0, 1L, 10L, 5L, false);
        byte[] lfh2 = createLFH("2.txt", 0, 2L, 20L, 10L, false);

        ByteBuffer bb = ByteBuffer.allocate(lfh1.length + lfh2.length);
        bb.put(lfh1);
        bb.put(lfh2);

        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        ZipArchiveEntry e1 = zais.getNextZipEntry();
        assertNotNull(e1);
        assertEquals("1.txt", e1.getName());

        ZipArchiveEntry e2 = zais.getNextZipEntry();
        assertNotNull(e2);
        assertEquals("2.txt", e2.getName());

        assertNull(zais.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_UTF8() throws IOException {
        // To trigger UTF8, we need to set the bit in GP flag.
        // GeneralPurposeBit.parse handles the bitmask.
        // bit 8 is usually UTF-8.
        ByteBuffer bb = ByteBuffer.allocate(100).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt(LFH_SIG);
        bb.putShort((short) 0x0200); 
        bb.putShort((short) 0x0100); // Bit 8 set: UTF-8
        bb.putShort((short) 0);      // method
        bb.putInt(0);                // time
        bb.putInt(0);                // crc
        bb.putShort((short) 0);      // unused
        bb.putInt(0);                // size

        String utf8Name = "tést.txt";
        byte[] nameBytes = utf8Name.getBytes(java.nio.charset.StandardCharsets.UTF_8);
        bb.putShort((short) nameBytes.length);
        bb.putShort((short) 0);      // extra
        bb.put(nameBytes);

        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zais.getNextZipEntry();
        assertNotNull(entry);
        assertEquals(utf8Name, entry.getName());
    }
}
